param(
    [string]$ProjectRoot = "E:\MY PROJECT FOLDER\AURA PROJECT\AURA-Butler-Android-Studio-v0.4.0-Native-Stable",
    [switch]$SkipBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "AURA v0.16.1 Owner Voice Permission Hotfix" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "Project: $ProjectRoot"
Write-Host ""
Write-Host "Repairs the v0.16 lint failure and creates a proper v0.16.1 APK:" -ForegroundColor Yellow
Write-Host " - explicitly re-checks RECORD_AUDIO inside captureSpeechSample()"
Write-Host " - handles SecurityException if Android revokes microphone access"
Write-Host " - bumps Android versionCode 23 -> 24"
Write-Host " - bumps versionName to 0.16.1-owner-voice-attention"
Write-Host " - preserves owner voice, attention sentinel, speaker model and all v0.16 reliability fixes"
Write-Host " - does NOT touch or redeploy Modal"
Write-Host ""

$AndroidRoot = Join-Path $ProjectRoot "android"
$OwnerFile = Join-Path $AndroidRoot "app\src\main\java\in\diganta\aurabutler\voice\OwnerVoiceGuard.kt"
$BuildFile = Join-Path $AndroidRoot "app\build.gradle.kts"
$Gradlew = Join-Path $AndroidRoot "gradlew.bat"

foreach ($Required in @($OwnerFile, $BuildFile, $Gradlew)) {
    if (-not (Test-Path -LiteralPath $Required)) {
        throw "Required file not found: $Required"
    }
}

$Manifest = @(
    [pscustomobject]@{
        Path = $OwnerFile
        Expected = "C3EFE6BA18B0045D6EFC2F22AF910EECDCC007ADA0B83C1499BA1B02AB81DE6D"
        Target = "86C4AA6669979C6631D2C3343DC3108E2FBFE9179085EB6BBAC76B11040013D8"
        Base64 = @'

'@
    },
    [pscustomobject]@{
        Path = $BuildFile
        Expected = "0B8D647DAA21C242DFE6D8A7F1F08D29EB0AD4A7045653E4C66154B0010FBA8B"
        Target = "C0D3C65D9DEB0082029BE910340D03568BF94E65AE525CDB5DCC542048457B68"
        Base64 = @'

'@
    }
)

Write-Host "==> Compatibility + hash preflight" -ForegroundColor Cyan
$NeedPatch = 0
foreach ($Entry in $Manifest) {
    $Hash = (Get-FileHash -Algorithm SHA256 -LiteralPath $Entry.Path).Hash.ToUpperInvariant()
    if ($Hash -eq $Entry.Target) {
        continue
    }
    if ($Hash -ne $Entry.Expected) {
        throw @"
Refusing to overwrite an unexpected file:
$($Entry.Path)

Expected current v0.16 SHA256:
$($Entry.Expected)

Corrected v0.16.1 SHA256:
$($Entry.Target)

Actual SHA256:
$Hash

Do not force this hotfix. Send the actual hash for review.
"@
    }
    $NeedPatch += 1
}
Write-Host "PASS: exact v0.16 baseline; $NeedPatch file(s) require patching" -ForegroundColor Green

Write-Host ""
Write-Host "==> Applying v0.16.1 hotfix" -ForegroundColor Cyan
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot ".aura-v0.16.1-backup\$Stamp"

foreach ($Entry in $Manifest) {
    $Hash = (Get-FileHash -Algorithm SHA256 -LiteralPath $Entry.Path).Hash.ToUpperInvariant()
    if ($Hash -eq $Entry.Target) {
        Write-Host "CURRENT: $($Entry.Path)" -ForegroundColor Green
        continue
    }

    $Rel = $Entry.Path.Substring($ProjectRoot.Length).TrimStart("\")
    $BackupPath = Join-Path $BackupRoot $Rel
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $BackupPath) | Out-Null
    Copy-Item -LiteralPath $Entry.Path -Destination $BackupPath -Force

    [System.IO.File]::WriteAllBytes(
        $Entry.Path,
        [System.Convert]::FromBase64String($Entry.Base64.Trim())
    )

    $After = (Get-FileHash -Algorithm SHA256 -LiteralPath $Entry.Path).Hash.ToUpperInvariant()
    if ($After -ne $Entry.Target) {
        throw "Write verification failed for $($Entry.Path). Expected $($Entry.Target), got $After"
    }
    Write-Host "PATCHED: $Rel" -ForegroundColor Green
}

$OwnerText = [System.IO.File]::ReadAllText($OwnerFile)
$BuildText = [System.IO.File]::ReadAllText($BuildFile)

if (-not $OwnerText.Contains("ContextCompat.checkSelfPermission(context, Manifest.permission.RECORD_AUDIO)")) {
    throw "Static validation failed: RECORD_AUDIO permission check is missing."
}
if (-not $OwnerText.Contains('throw SecurityException("Microphone permission is required for owner voice enrollment.")')) {
    throw "Static validation failed: permission-denied path is missing."
}
if (-not $OwnerText.Contains("Android denied microphone access during owner voice enrollment.")) {
    throw "Static validation failed: SecurityException recovery path is missing."
}
if (-not $BuildText.Contains('versionCode = 24')) {
    throw "Static validation failed: versionCode 24 is missing."
}
if (-not $BuildText.Contains('versionName = "0.16.1-owner-voice-attention"')) {
    throw "Static validation failed: v0.16.1 versionName is missing."
}

Write-Host "PASS [static]: microphone permission is checked at the capture boundary" -ForegroundColor Green
Write-Host "PASS [static]: microphone revocation is handled safely" -ForegroundColor Green
Write-Host "PASS [static]: Android version is v0.16.1 / versionCode 24" -ForegroundColor Green

if ($SkipBuild) {
    Write-Host ""
    Write-Host "SkipBuild requested. Source repaired; Gradle was not run." -ForegroundColor Yellow
    exit 0
}

foreach ($Candidate in @(
    "E:\Program Files\Android\Android Studio\jbr",
    "C:\Program Files\Android\Android Studio\jbr"
)) {
    if (Test-Path -LiteralPath (Join-Path $Candidate "bin\java.exe")) {
        $env:JAVA_HOME = $Candidate
        break
    }
}

Write-Host ""
Write-Host "==> Android verification" -ForegroundColor Cyan
Write-Host "Tasks: testDebugUnitTest lintDebug assembleDebug"
Write-Host ""

Push-Location $AndroidRoot
try {
    & $Gradlew --no-daemon testDebugUnitTest lintDebug assembleDebug
    $GradleExit = $LASTEXITCODE
}
finally {
    Pop-Location
}

if ($GradleExit -ne 0) {
    throw "Gradle verification failed with exit code $GradleExit. Send the first FAILED task."
}

Write-Host ""
Write-Host "PASS: JVM unit tests" -ForegroundColor Green
Write-Host "PASS: Android lintDebug" -ForegroundColor Green
Write-Host "PASS: Debug APK build" -ForegroundColor Green

$BuiltApk = Join-Path $AndroidRoot "app\build\outputs\apk\debug\app-debug.apk"
if (-not (Test-Path -LiteralPath $BuiltApk)) {
    throw "Gradle succeeded but app-debug.apk was not found."
}

$FinalApk = Join-Path $ProjectRoot "AURA-v0.16.1-owner-voice-attention-debug.apk"
Copy-Item -LiteralPath $BuiltApk -Destination $FinalApk -Force

Write-Host ""
Write-Host "============================================================" -ForegroundColor Green
Write-Host "SUCCESS: AURA v0.16.1 Android verification passed." -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host "APK: $FinalApk"
Write-Host ""
Write-Host "Install this APK as an UPDATE; do not uninstall AURA first."
Write-Host "Then run Test-AURA-AutoQA-v10.ps1 -Full -SkipCloud."
